    50,
    67,
    84,
    101,
};
string[] messages =
{
    "cache miss for key 412",
    "retrying request 28 (attempt 2)",
    "connection pool at 76% capacity",
    "GC pause 8 ms",
    "flushed 960 records"
};
string Number(double value) => value.ToString("#,0", CultureInfo.InvariantCulture);
// Layout: retain every worker row, the session counters, update sparkline, CPU chart and captured output.
IWidget Frame(int tick)
{
    Lanes lanes = new Lanes("workers");
    for (int id = 0; id < Workers; id++)
    {
        Lane lane = lanes.Add("w" + id, "worker " + (id + 1).ToString("00", CultureInfo.InvariantCulture), 100000);
        if (tick > 0)
        {
            lane.Value = tick == 6 ? 100000 : tick * 3200 + id * 97 % 400;
            lane.Failed = (int)lane.Value / 97;
            lane.Warned = (int)lane.Value / 17;
            lane.Passed = (int)lane.Value - lane.Failed - lane.Warned;
            lane.Status = tick == 6 ? StatusKind.Pass : StatusKind.Running;
            lane.Detail = actions[(id + tick) % actions.Length] + " item " + Number(lane.Value);
        }
    }

    int samples = tick * 8;
    long posted = tick * 128000L;
    KeyValueList stats = new KeyValueList("stats").Add("Updates posted", Number(posted)).Add("Updates applied", Number(posted)).Add("Update rate", samples == 0 ? "-" : Number(sampleRates[samples - 1]) + "/s").Add("Frames", Number(tick * 15)).Add("Frame rate", tick == 0 ? "-" : "15.0 fps").Add("CPU", samples == 0 ? "-" : Number(sampleCpu[samples - 1]) + "%").Add("CPU share", samples == 0 ? "-" : (sampleCpu[samples - 1] / 8).ToString("0.0", CultureInfo.InvariantCulture) + "% of 8 cores").Add("Stray writes", (tick * 4).ToString(CultureInfo.InvariantCulture)).Add("Dropped / errors", "0 / 0");
    Sparkline rate = new Sparkline("rate")
    {
        Height = 3,
        Unit = "/s"
    };
    rate.AddRange(sampleRates.Take(samples));
    LineChart cpu = new LineChart("cpu")
    {
        Height = 6,
        Minimum = 0,
        Unit = "%"
    };
    cpu.AddSeries("cpu", ThemeToken.Accent2);
    foreach (double value in sampleCpu.Take(samples))
        cpu.Add("cpu", value);
    LogRegion output = new LogRegion
    {
        PreferredHeight = 6,
        ShowElapsed = false
    };
    for (int i = 0; i < tick * 4; i++)
        output.Write("stray-" + i % 4 + "-" + i + ": FakeLib: " + messages[i % 5], i % 7 == 0 ? "err" : "info");
    Rows body = new Rows(new Columns().Add(new Panel() { Title = "Workers", Content = lanes }, LayoutSize.Fraction(2.2)).Add(new Panel() { Title = "Session", Content = new Rows(stats, new Rule("updates/s"), rate, new Rule("CPU % (100% = one core)"), cpu) })).Add(new Panel() { Title = "Captured output", Content = output }, LayoutSize.Fraction());
    return new Dashboard()
    {
        Content = body,
        Title = "[bold]Stress test[/]",
        Subtitle = "32 workers · captured tool output · 6s",
        ShowElapsed = false,
        Footer = "[muted]32 workers    15 frames/s    Ctrl+C stop[/]"
    };
}

// Behaviour: show seven samples through the ordinary live session.
RegionWidget screen = new RegionWidget(widgetId: "stress", content: Frame(0));
using LiveSession session = new LiveSession(screen);
try
{
    session.Run(live =>
    {
        for (int tick = 0; tick <= 6; tick++)
        {
            live.Cancellation.ThrowIfCancellationRequested();
            screen.Handle(live).Set(Frame(tick));
            live.Delay(TimeSpan.FromSeconds(1));
        }
    });
}
catch (OperationCanceledException cancelled)when (cancelled.CancellationToken == session.Cancellation)
{
    // Ctrl+C is a normal way to leave the demo, after the session restores the terminal.
    return;
}

