Choice[] Parts() => components.Select(p => new Choice(p.Id, p.Name) { Group = p.Group, Description = p.Description, Badge = RichText.Plain(p.Size, new RichStyle(ThemeToken.Muted)), Selected = p.Selected, DisabledReason = p.Disabled }).ToArray();
Choice[] Servers(string? region) => endpoints.Where(e => e.Region == region).Select(e => new Choice(e.Host) { Description = e.City, Badge = RichText.Plain(e.Latency, new RichStyle(ThemeToken.Muted)), DisabledReason = e.Disabled }).ToArray();
// Layout: the native form owns validation, dependent choices, editors and review.
Form BuildForm()
{
    Form form = new Form("Install Toolbox Agent")
    {
        Command = "Install-ToolboxAgent",
        SubmitText = "Install",
        Description = "Sets up the agent that runs toolbox tasks on this machine."
    };
    FormPage location = form.Page("Location");
    PathField path = location.Path("Path", "Install folder");
    path.PathKind = PathKind.Folder;
    path.Default = installFolder;
    path.Required = true;
    path.ParameterName = "Path";
    path.Help = "Created during installation. Tab completes folder names.";
    PathField data = location.Path("Data", "Data folder");
    data.PathKind = PathKind.Folder;
    data.Default = dataFolder;
    data.ParameterName = "DataPath";
    data.Help = "Logs, reports and the local queue.";
    ToggleField launcher = location.Toggle("Launcher", "Launcher entry");
    launcher.Default = true;
    launcher.ParameterName = "Launcher";
    FormPage parts = form.Page("Components");
    ChoiceField selection = parts.MultiSelect("Components", "Components", Parts());
    selection.Minimum = 1;
    selection.ParameterName = "Component";
    selection.Help = "Space toggles, Ctrl+A selects all, Enter closes the list.";
    FormPage service = form.Page("Service");
    ChoiceField account = service.Select("Account", "Service account", accounts);
    account.Default = "ServiceUser";
    account.ParameterName = "Account";
    TextField user = service.Text("UserName", "User name");
    user.VisibleWhen = v => Equals(v["Account"], "Custom");
    user.Required = true;
    user.Placeholder = "toolbox-agent";
    user.ParameterName = "UserName";
    SecretField password = service.Secret("Password", "Password");
    password.VisibleWhen = v => Equals(v["Account"], "Custom");
    password.ParameterName = "Password";
    password.CommandPlaceholder = "(Read-Host -AsSecureString)";
    ToggleField automatic = service.Toggle("AutoStart", "Start automatically");
    automatic.Default = true;
    automatic.ParameterName = "AutoStart";
    FormPage connection = form.Page("Connection");
    ChoiceField region = connection.Select("Region", "Region", new[] { new Choice("eu", "Europe"), new Choice("us", "Americas"), new Choice("ap", "Asia Pacific") });
    region.Default = "eu";
    region.Required = true;
    region.ParameterName = "Region";
    region.Help = "Choosing a region loads its servers.";
    ChoiceField server = connection.Select("Server", "Server");
    server.DependsOn.Add("Region");
    server.Required = true;
    server.ParameterName = "Server";
    server.LoadChoices = async (values, token) =>
    {
        await Task.Delay(300, token);
        return Servers(values.Get<string>("Region"));
    };
    server.Help = "Loaded for the chosen region; Esc cancels loading.";
    NumberField port = connection.Number("Port", "Port");
    port.Integer = true;
    port.Minimum = 1;
    port.Maximum = 65535;
    port.Default = 443m;
    port.ParameterName = "Port";
    ToggleField proxy = connection.Toggle("UseProxy", "Use a proxy");
    proxy.ParameterName = "UseProxy";
    TextField address = connection.Text("Proxy", "Proxy address");
    address.VisibleWhen = v => v.Get<bool>("UseProxy");
    address.Required = true;
    address.Placeholder = "http://proxy.example.test:8080";
    address.ParameterName = "Proxy";
    return form;
}

// Behaviour: edit every page, review, then run a bounded in-memory installation.
FormResult answers = BuildForm().Show();
if (!answers.Submitted)
    return;
StatusList install = new StatusList("steps");
foreach (string label in installSteps)
    install.Add(label, StatusKind.Pending);
ProgressBar bar = new ProgressBar("Install")
{
    Total = 40
};
Dashboard dashboard = new DashboardBuilder("Installing Toolbox Agent").Subtitle(Markup.Escape(answers.Values.Get<string>("Path"))).Panel("Steps", install).Add(new Padding() { Bottom = 0, Right = 1, Top = 0, Left = 1, Content = bar }).BuildDashboard();
using (LiveSession session = new LiveSession(dashboard))
{
    try
    {
        session.Run(s =>
        {
            StatusListHandle status = install.Handle(s);
            ProgressHandle progress = bar.Handle(s);
            foreach (string label in installSteps)
            {
                status.Set(label, StatusKind.Running);
                progress.Label(label);
                for (int i = 0; i < 10; i++)
                {
                    s.Cancellation.ThrowIfCancellationRequested();
                    progress.Advance();
                    s.Delay(TimeSpan.FromMilliseconds(90));
                }

                status.Set(label, StatusKind.Pass);
            }

            progress.Complete();
        });
    }
    catch (OperationCanceledException cancelled)when (cancelled.CancellationToken == session.Cancellation)
    {
        // Ctrl+C is a normal way to leave the demo, after the session restores the terminal.
        return;
    }
}

Terminal.Write(new Panel() { Title = "Toolbox Agent installed", Content = new KeyValueList().Add("Install folder", Markup.Escape(answers.Values.Get<string>("Path"))).Add("Components", Markup.Escape(string.Join(", ", answers.Values.GetList<object>("Components")))).Add("Server", Markup.Escape(answers.Values.Get<string>("Server"))).Add("Steps done", "4", StatusKind.Pass).Add("Launch", "toolbox") });
