powershell.text:
# Server toolbox: menus, selections, review, live work and actionable results.
# Synthetic data and timings; reports and notifications stay in memory. No remote effects.
Import-Module -Name ConsoleMonster
$ErrorActionPreference = 'Stop'

# Data: fictional inventory, operations and findings kept in memory.
$inventory = @(
    [pscustomobject] @{ Name = 'FS01'; Domain = 'lab.example.test'; Site = 'Warsaw'; Role = 'File'; Detail = 'Windows Server 2022'; Offline = '' }
    [pscustomobject] @{ Name = 'FS02'; Domain = 'lab.example.test'; Site = 'Warsaw'; Role = 'File'; Detail = 'Windows Server 2022'; Offline = '' }
    [pscustomobject] @{ Name = 'WEB01'; Domain = 'lab.example.test'; Site = 'Warsaw'; Role = 'Web'; Detail = 'Windows Server 2025'; Offline = '' }
    [pscustomobject] @{ Name = 'SQL01'; Domain = 'lab.example.test'; Site = 'Warsaw'; Role = 'Database'; Detail = 'Windows Server 2019'; Offline = '' }
    [pscustomobject] @{ Name = 'FS11'; Domain = 'lab.example.test'; Site = 'Berlin'; Role = 'File'; Detail = 'Windows Server 2022'; Offline = '' }
    [pscustomobject] @{ Name = 'WEB11'; Domain = 'lab.example.test'; Site = 'Berlin'; Role = 'Web'; Detail = 'Windows Server 2025'; Offline = '' }
    [pscustomobject] @{ Name = 'PRN11'; Domain = 'lab.example.test'; Site = 'Berlin'; Role = 'Print'; Detail = 'Windows Server 2016'; Offline = 'offline since 09:12' }
    [pscustomobject] @{ Name = 'BKP21'; Domain = 'lab.example.test'; Site = 'Dublin'; Role = 'Backup'; Detail = 'Windows Server 2022'; Offline = '' }
    [pscustomobject] @{ Name = 'SQL21'; Domain = 'lab.example.test'; Site = 'Dublin'; Role = 'Database'; Detail = 'Windows Server 2022'; Offline = '' }
    [pscustomobject] @{ Name = 'LAB01'; Domain = 'lab.example.test'; Site = 'Lab'; Role = 'Test'; Detail = 'Windows Server 2025'; Offline = '' }
    [pscustomobject] @{ Name = 'LAB02'; Domain = 'lab.example.test'; Site = 'Lab'; Role = 'Test'; Detail = 'Windows Server 2025'; Offline = 'maintenance until Friday' }
)
$catalog = @(
    [pscustomobject] @{ Id = 'DiskCleanup'; Name = 'Disk cleanup'; Category = 'Maintenance'; Description = 'Removes temporary files and old update caches.'; Expected = 'cache under 1 GB'; Minutes = 3.0; Changes = $true }
    [pscustomobject] @{ Id = 'LogRotation'; Name = 'Log rotation'; Category = 'Maintenance'; Description = 'Compresses logs older than 7 days.'; Expected = 'retention 90 days'; Minutes = 2.0; Changes = $true }
    [pscustomobject] @{ Id = 'RestartPending'; Name = 'Pending restart check'; Category = 'Maintenance'; Description = 'Reports restarts waiting after updates.'; Expected = 'no restart pending'; Minutes = 1.0; Changes = $false }
    [pscustomobject] @{ Id = 'PatchStatus'; Name = 'Patch status'; Category = 'Security'; Description = 'Lists missing security updates.'; Expected = '0 missing'; Minutes = 2.0; Changes = $false }
    [pscustomobject] @{ Id = 'Certificates'; Name = 'Certificate expiry'; Category = 'Security'; Description = 'Finds certificates expiring within 30 days.'; Expected = '30+ days'; Minutes = 1.0; Changes = $false }
    [pscustomobject] @{ Id = 'LocalAdmins'; Name = 'Local administrators audit'; Category = 'Security'; Description = 'Compares local Administrators with the approved list.'; Expected = 'approved list'; Minutes = 1.0; Changes = $false }
    [pscustomobject] @{ Id = 'Firewall'; Name = 'Firewall rules review'; Category = 'Security'; Description = 'Flags inbound allow rules open to any address.'; Expected = 'scoped rules'; Minutes = 2.0; Changes = $false }
    [pscustomobject] @{ Id = 'EventErrors'; Name = 'Event log errors'; Category = 'Health'; Description = 'Summarizes errors from the last 24 hours.'; Expected = 'under 20'; Minutes = 1.0; Changes = $false }
    [pscustomobject] @{ Id = 'Services'; Name = 'Service health'; Category = 'Health'; Description = 'Checks and restarts stopped automatic services.'; Expected = 'all running'; Minutes = 1.0; Changes = $true }
    [pscustomobject] @{ Id = 'DiskSpace'; Name = 'Disk space'; Category = 'Health'; Description = 'Warns below 15% and fails below 5% free.'; Expected = '15% free'; Minutes = 1.0; Changes = $false }
    [pscustomobject] @{ Id = 'Uptime'; Name = 'Uptime and reboots'; Category = 'Health'; Description = 'Reports unexpected reboots in the last 30 days.'; Expected = '0 unexpected'; Minutes = 1.0; Changes = $false }
)
$findings = @{
    'FS02/PatchStatus' = [pscustomobject] @{ Status = 'Fail'; Actual = '3 updates missing for 41 days' }
    'WEB01/Certificates' = [pscustomobject] @{ Status = 'Warn'; Actual = 'expires in 24 days' }
    'SQL01/DiskSpace' = [pscustomobject] @{ Status = 'Fail'; Actual = '4% free on data volume' }
    'FS11/Services' = [pscustomobject] @{ Status = 'Warn'; Actual = '1 service restarted' }
    'FS01/DiskCleanup' = [pscustomobject] @{ Status = 'Warn'; Actual = '1.4 GB remains' }
}
$history = @(
    [pscustomobject] @{ When = 'Mon 19 Oct 21:04'; Servers = 3; Tasks = 4; Passed = 10; Warnings = 1; Failed = 1; Elapsed = (New-TimeSpan -Seconds 372) }
    [pscustomobject] @{ When = 'Tue 20 Oct 07:30'; Servers = 2; Tasks = 3; Passed = 6; Warnings = 0; Failed = 0; Elapsed = (New-TimeSpan -Seconds 66) }
)
$reportRoot = 'Reports/Toolbox'
$plan = @{
    Domain = 'lab.example.test'
    Targets = @($inventory | Where-Object -FilterScript { $_.Domain -eq 'lab.example.test' -and -not $_.Offline } | Select-Object -First 4)
    Checks = @($catalog | Where-Object -Property Id -In -Value @('DiskCleanup', 'PatchStatus', 'Certificates', 'DiskSpace'))
    History = $history
    CompletedWork = @()
    Parallel = 3
    Report = $reportRoot
    Format = 'Html'
    Notify = $false
    Email = 'ops@example.test'
    DryRun = $false
}

function Get-Work {
    for ($ci = 0; $ci -lt $plan.Checks.Count; $ci++) {
        for ($ni = 0; $ni -lt $plan.Targets.Count; $ni++) {
            $node = $plan.Targets[$ni]
            $check = $plan.Checks[$ci]
            $outcome = $findings["$($node.Name)/$($check.Id)"]
            [pscustomobject] @{ Node = $node; Check = $check; Status = $(if ($outcome) { $outcome.Status } else { 'Pass' }); Actual = $(if ($outcome) { $outcome.Actual } else { $check.Expected }) }
        }
    }
}
function Get-Verdict {
    param(
        $Work
    )

    if (@($Work | Where-Object -Property Status -EQ -Value Fail).Count) { 'Fail' } elseif (@($Work | Where-Object -Property Status -EQ -Value Warn).Count) { 'Warn' } else { 'Pass' }
}
function Get-Findings {
    param(
        $Work
    )

    $rows = @($Work | Where-Object -Property Status -NE -Value Pass | ForEach-Object -Process {
            [pscustomobject] @{ Server = $_.Node.Name; Task = $_.Check.Name; Expected = $_.Check.Expected; Actual = New-ConsoleText -Text $_.Actual -Role $_.Status }
        })
    # Explicit text presenters keep the automatic PowerShell value shaping aligned with C#.
    $columns = @(
        @{ Name = 'Server'; Presenter = 'Text' }
        @{ Name = 'Task'; Presenter = 'Text' }
        @{ Name = 'Expected'; Presenter = 'Text' }
    )
    $columns += @{
        Name = 'Actual'
        Flexible = $true
    }
    if ($rows.Count) {
        $rows | Show-ConsoleTable -Property $columns -Border Minimal -NoSort -AsWidget
    }
    else {
        New-ConsoleTable -WidgetId findings -Border Minimal -Live -Columns $columns
    }
}
function Get-History {
    $rows = @(for ($index = $plan.History.Count - 1; $index -ge 0; $index--) {
            $plan.History[$index]
        })
    $columns = @(
        @{ Name = 'When'; Presenter = 'Text' }
        @{ Name = 'Servers'; Presenter = 'Text' }
        @{ Name = 'Tasks'; Presenter = 'Text' }
        @{ Name = 'Result'; Expression = { "$($_.Passed) passed · $($_.Warnings) warn · $($_.Failed) failed" }; Presenter = 'Text' }
        @{ Name = 'Duration'; Expression = { $_.Elapsed.ToString('hh\:mm\:ss') }; Presenter = 'Text' }
    )
    $rows | Show-ConsoleTable -Property $columns -Border Minimal -NoSort -AsWidget
}
function Get-Preview {
    param(
        $Check
    )

    New-ConsoleRows -Gap 1 -Content {
        New-ConsoleText -Text $Check.Description
        New-ConsoleKeyValue -Markup -InputObject ([ordered] @{
                Group = $Check.Category
                Expected = $Check.Expected
                Duration = "about $($Check.Minutes) min per server"
                Changes = $(if ($Check.Changes) { '[warn]yes[/]' } else { '[pass]no[/]' })
                Parameter = $Check.Id
            })
    }
}

# Layout: build the dashboard from the completed and active work.
function Get-RunBody {
    param(
        $Work,
        [int] $Done,
        [int] $Phase
    )

    $finished = @($Work | Select-Object -First $Done)
    $active = if ($Phase -eq 2) { @($Work | Select-Object -Skip $Done | Where-Object -FilterScript { $_.Check.Id -eq $Work[$Done].Check.Id } | Select-Object -First $plan.Parallel) } else { @() }
    $counter = [ordered] @{
        passed = @($finished | Where-Object -Property Status -EQ -Value Pass).Count
        warnings = @($finished | Where-Object -Property Status -EQ -Value Warn).Count
        failed = @($finished | Where-Object -Property Status -EQ -Value Fail).Count
    }
    New-ConsoleRows -Content {
        New-ConsoleSummaryBar -Total $Work.Count -Counter $counter -ElapsedSeconds ($Done * .24 / $plan.Parallel) -Value $Done
        New-ConsolePhases -Content {
            $names = @('Discover', 'Connect', 'Tasks', 'Report')
            for ($i = 0; $i -lt $names.Count; $i++) {
                $status = if ($i -lt $Phase) {
                    if ($i -eq 2) {
                        Get-Verdict -Work $finished
                    }
                    else {
                        'Pass'
                    }
                }
                elseif ($i -eq $Phase) {
                    'Running'
                }
                else {
                    'Pending'
                }
                [pscustomobject]@{ Label = $names[$i]; Status = $status }
            }
        }
        $lanes = New-ConsoleLanes -WidgetId lanes -Content {
            foreach ($node in $plan.Targets) {
                $planned = @($Work | Where-Object -FilterScript { $_.Node.Name -eq $node.Name })
                $ready = @($finished | Where-Object -FilterScript { $_.Node.Name -eq $node.Name })
                $doing = @($active | Where-Object -FilterScript { $_.Node.Name -eq $node.Name })
                $status = if ($ready.Count -eq $planned.Count) {
                    Get-Verdict -Work $ready
                }
                elseif ($doing.Count) {
                    'Running'
                }
                else {
                    'Pending'
                }
                $detail = if ($doing.Count) { $doing[0].Check.Name } elseif ($ready.Count) { $ready[-1].Check.Name } else { $null }
                [pscustomobject]@{ Key = $node.Name; Label = (New-ConsoleText -Text "$($node.Name)  $($node.Site)"); Total = $planned.Count; Status = $status; Detail = $detail; Passed = @($ready | Where-Object -Property Status -EQ -Value Pass).Count; Warned = @($ready | Where-Object -Property Status -EQ -Value Warn).Count; Failed = @($ready | Where-Object -Property Status -EQ -Value Fail).Count; Value = $ready.Count }
            }
        }
        New-ConsoleColumns -CollapseBelow 90 -Content {
            New-ConsolePanel -Title Servers -Content { $lanes }
            New-ConsolePanel -Title 'Run options' -Content {
                New-ConsoleKeyValue -InputObject ([ordered] @{
                        Targets = "$($plan.Targets.Count) servers"
                        Tasks = "$($plan.Checks.Count) per server"
                        Parallel = [string] $plan.Parallel
                        Report = $plan.Format.ToUpperInvariant()
                        'Dry run' = $(if ($plan.DryRun) { 'yes' } else { 'no' })
                    })
            }
        }
        New-ConsolePanel -Title Findings -Content { Get-Findings -Work $finished }
        New-ConsolePanel -Title Log -Content {
            New-ConsoleLogRegion -NoElapsed -Height 7 -Content {
                [pscustomobject]@{ Message = "Inventory: $($plan.Domain) · $($plan.Targets.Count) servers · $($Work.Count) tasks" }
                if ($Phase -ge 1) {
                    [pscustomobject]@{ Message = "Connecting up to $($plan.Parallel) servers at a time" }
                }
                foreach ($w in @($finished | Select-Object -Last 5)) {
                    $level = if ($w.Status -eq 'Fail') { 'err' } elseif ($w.Status -eq 'Warn') { 'warn' } else { 'info' }
                    [pscustomobject]@{ Message = "$($w.Node.Name) · $($w.Check.Name): $($w.Actual)"; Level = $level }
                }
                if ($Phase -ge 3) {
                    [pscustomobject]@{ Message = "Preparing $($plan.Format.ToUpperInvariant()) report: $($plan.Report)" }
                }
                if ($Phase -ge 4) {
                    $text = if ($plan.Notify) { "Report ready · recipient $($plan.Email)" } else { "Report ready · $(@($finished | Where-Object -Property Status -NE -Value Pass).Count) findings to review" }
                    [pscustomobject]@{ Message = $text }
                }
            }
        }
    }
}

# Behaviour: native form/menu navigation, then a bounded run with cancellation and history.
function Invoke-Work {
    param(
        $Context,
        $Work
    )

    $plan.CompletedWork = @($Work)
    $dashboard = New-ConsoleDashboard -Title '[bold]Server toolbox[/]' -Subtitle $plan.Domain `
        -Footer 'Ctrl+C cancel · results keep the findings' -Content {
        New-ConsoleRegion -WidgetId body -Content { Get-RunBody -Work $Work -Done 0 -Phase 0 }
    }
    $runState = @{ Finished = $false }
    $outcome = $Context.Run($dashboard, {
            param($Run)
            $phase = 0
            $done = 0
            foreach ($phase in 0, 1) {
                Update-Console -WidgetId body -Content { Get-RunBody -Work $Work -Done 0 -Phase $phase }
                $Run.Session.Delay([timespan]::FromMilliseconds(240))
                if ($Run.CancellationToken.IsCancellationRequested) {
                    return New-ConsoleMenuRunResult -Title 'Run cancelled' -Status Warn -Summary "$done of $($Work.Count) operations completed."
                }
            }
            foreach ($group in @($Work | Group-Object -Property { $_.Check.Id })) {
                for ($offset = 0; $offset -lt $group.Count; $offset += $plan.Parallel) {
                    Update-Console -WidgetId body -Content { Get-RunBody -Work $Work -Done $done -Phase 2 }
                    $Run.Session.Delay([timespan]::FromMilliseconds(240))
                    if ($Run.CancellationToken.IsCancellationRequested) {
                        return New-ConsoleMenuRunResult -Title 'Run cancelled' -Status Warn -Summary "$done of $($Work.Count) operations completed."
                    }
                    $done += [math]::Min($plan.Parallel, $group.Count - $offset)
                }
            }
            foreach ($phase in 3, 4) {
                Update-Console -WidgetId body -Content { Get-RunBody -Work $Work -Done $done -Phase $phase }
                $Run.Session.Delay([timespan]::FromMilliseconds(240))
                if ($Run.CancellationToken.IsCancellationRequested) {
                    return New-ConsoleMenuRunResult -Title 'Run cancelled' -Status Warn -Summary "$done of $($Work.Count) operations completed."
                }
            }
            $result = Get-Result -Work $Work
            $runState.Finished = $true
            $result
        })
    if (-not $runState.Finished) {
        return
    }
    $plan.History += [pscustomobject] @{ When = 'Tue 20 Oct 09:30'; Servers = @($Work.Node.Name | Select-Object -Unique).Count; Tasks = @($Work.Check.Id | Select-Object -Unique).Count; Passed = @($Work | Where-Object -Property Status -EQ -Value Pass).Count; Warnings = @($Work | Where-Object -Property Status -EQ -Value Warn).Count; Failed = @($Work | Where-Object -Property Status -EQ -Value Fail).Count; Elapsed = $outcome.Elapsed }
}
function Get-Result {
    param(
        $Work
    )

    $summary = "$($Work.Count) tasks on $(@($Work.Node.Name | Select-Object -Unique).Count) servers. Review the findings and choose the next action."
    # Retain the current run for next actions on the menu's owning thread.
    $next = [ordered] @{
        'View report' = {
            $MenuContext.ShowResult((New-ConsoleMenuRunResult -Title "Report · $($plan.Format.ToUpperInvariant())" `
                        -Status (Get-Verdict -Work $plan.CompletedWork) -Summary $plan.Report -Details (Get-Findings -Work $plan.CompletedWork)))
        }
    }
    if (@($Work | Where-Object -Property Status -EQ -Value Fail).Count) {
        $next['Rerun failed tasks'] = { Invoke-Work -Context $MenuContext -Work @($plan.CompletedWork | Where-Object -Property Status -EQ -Value Fail) }
    }
    $next['View history'] = { $MenuContext.ShowResult((New-ConsoleMenuRunResult -Title 'Run history' -Details (Get-History))) }
    New-ConsoleMenuRunResult -Title 'Run finished' -Status (Get-Verdict -Work $Work) -Summary $summary -Details (Get-Findings -Work $Work) `
        -Figure ([ordered] @{
            passed = @($Work | Where-Object -Property Status -EQ -Value Pass).Count
            warnings = @($Work | Where-Object -Property Status -EQ -Value Warn).Count
            failed = @($Work | Where-Object -Property Status -EQ -Value Fail).Count
        }) `
        -FigureStatus @{
        passed = 'Pass'
        warnings = $(if (@($Work | Where-Object -Property Status -EQ -Value Warn).Count) { 'Warn' } else { 'Pass' })
        failed = $(if (@($Work | Where-Object -Property Status -EQ -Value Fail).Count) { 'Fail' } else { 'Pass' })
    } -Next $next
}
function Get-OptionFields {
    param(
        [string] $Page
    )

    $pageOption = @{}
    if ($Page) {
        $pageOption.Page = $Page
    }
    New-ConsoleField @pageOption -Key Parallel -Label 'Servers at a time' -Type Number -Integer -Minimum 1 -Maximum 16 -Default 3 -ParameterName ThrottleLimit
    New-ConsoleField @pageOption -Key Report -Label 'Report folder' -Type Path -Kind Folder -Default $reportRoot -ParameterName ReportPath
    New-ConsoleField @pageOption -Key Format -Label 'Report format' -Type Select -Choices @(
        [pscustomobject] @{ Id = 'Html'; Name = 'HTML' }
        [pscustomobject] @{ Id = 'Csv'; Name = 'CSV' }
        [pscustomobject] @{ Id = 'Json'; Name = 'JSON' }
    ) -Display Name -CommandValue Id -Default Html -ParameterName Format
    New-ConsoleField @pageOption -Key Notify -Label 'Email the report' -Type Toggle -ParameterName Notify
    New-ConsoleField @pageOption -Key Email -Label Recipient -Default 'ops@example.test' -ParameterName To -Required `
        -VisibleWhen { $Values.Notify } -Validator { if ($_ -notlike '*@*') { 'Enter an email address' } }
    New-ConsoleField @pageOption -Key DryRun -Label 'Dry run' -Type Toggle -ParameterName WhatIf
}
function Set-Options {
    param(
        $Values
    )

    foreach ($name in 'Parallel', 'Report', 'Format', 'Notify', 'Email', 'DryRun') {
        $plan[$name] = $Values[$name]
    }
}
$formOptions = @{
    Title = 'Options'
    NoReview = $true
    SubmitText = 'Save'
    PageDescriptions = @{ Options = 'Parallelism, reports and notifications.' }
    Content = { Get-OptionFields }
}
$options = New-ConsoleForm @formOptions
$targetItem = New-ConsoleMenuItem -Label Targets -Hotkey t -IconName Targets -Description 'Inventory grouped by site; unavailable servers stay visible.' `
    -LoadChoices {
    param($Values, $Inventory)
    Start-Sleep -Milliseconds 700
    $Inventory
} -ArgumentList (, $inventory) -Display Name -GroupBy Site -Describe Detail `
    -Selected $plan.Targets -Minimum 1 -ChoiceBadge Role -ChoiceDisabledReason Offline -Preview {
    New-ConsoleKeyValue -InputObject ([ordered] @{
            Server = $_.Name
            Site = $_.Site
            Role = $_.Role
            OS = $_.Detail
        })
}
$taskItem = New-ConsoleMenuItem -Label Tasks -Hotkey k -IconName Tasks -MultiSelect $catalog -Display Name -GroupBy Category `
    -Describe Description -Selected $plan.Checks -Minimum 1 -Preview { Get-Preview -Check $_ } -ChoiceBadge {
    $badge = $(if ($_.Changes) { 'changes · ' }) + "~$($_.Minutes) min"
    New-ConsoleText -Text $badge -Role $(if ($_.Changes) { 'Warn' } else { 'Muted' })
}
$menu = New-ConsoleMenu -Title 'Server toolbox' -Layout Shell -Subtitle 'Tue 20 Oct 2026 · 09:30' -Content {
    $targetItem
    $taskItem
    New-ConsoleMenuItem -Label Options -Hotkey o -IconName Settings -Form $options -OnSubmit { Set-Options -Values $Values }
    New-ConsoleMenuItem -Label Presets -Hotkey p -IconName Favorite -Presets
    [pscustomobject]@{ Name = 'Morning · Warsaw'; Form = $options; Values = @{
        Parallel = 2
        DryRun = $true
    }; Selections = @{
        $targetItem = @($inventory | Where-Object -Property Site -EQ -Value Warsaw)
        $taskItem = @($catalog | Where-Object -Property Id -In -Value 'PatchStatus', 'Certificates', 'DiskSpace')
    }; Preview = { New-ConsoleKeyValue -InputObject ([ordered] @{
                Scope = 'Warsaw servers'
                Tasks = 'Security and disk space'
                'Dry run' = 'yes'
            }) } }
    [pscustomobject]@{ Name = 'Health · all sites'; Selections = @{
        $targetItem = @($inventory | Where-Object -FilterScript { -not $_.Offline })
        $taskItem = @($catalog | Where-Object -Property Id -In -Value 'EventErrors', 'Services', 'DiskSpace', 'Uptime')
    } }
    New-ConsoleMenuItem -Separator
    New-ConsoleMenuItem -Label 'Review & run' -Hotkey r -IconName Run -Review {
        $plan.Targets = @($targetItem.Selection | ForEach-Object -Process { $_ })
        $plan.Checks = @($taskItem.Selection | ForEach-Object -Process { $_ })
        $values = $options.GetValues()
        Set-Options -Values $values
        $problems = @(
            if (-not $plan.Targets.Count) { 'Pick at least one target' }
            if (-not $plan.Checks.Count) { 'Pick at least one task' }
            if ($plan.Notify -and $plan.Email -notlike '*@*') { 'Enter the email recipient in Options' }
        )
        $commandArguments = [ordered] @{
            ComputerName = $plan.Targets.Name
            Task = $plan.Checks.Id
        }
        $command = Format-ConsoleCommand -Command Invoke-ServerToolbox -Arguments $commandArguments
        @{
            Title = 'Review & run'
            Description = 'Everything the run uses; the command carries the same options.'
            Rows = [ordered] @{
                Targets = $plan.Targets.Name -join ', '
                Tasks = $plan.Checks.Name -join ', '
                'Servers at a time' = [string] $plan.Parallel
                Report = "$($plan.Report) ($($plan.Format.ToUpperInvariant()))"
                Email = $(if ($plan.Notify) { $plan.Email } else { 'off' })
                'Dry run' = $(if ($plan.DryRun) { 'yes' } else { 'no' })
            }
            Problems = $problems
            Command = "$command $($options.BuildCommand())"
            Run = { Invoke-Work -Context $MenuContext -Work @(Get-Work) }
        }
    }
    New-ConsoleMenuItem -Label History -Hotkey h -IconName List -Detail { "$($plan.History.Count) runs" } -Page { Get-History }
    New-ConsoleMenuItem -Separator
    New-ConsoleMenuItem -Label Quit -Exit
}
Show-ConsoleMenu -Menu $menu -Layout Shell -AppName 'Server toolbox gallery'

csharp.text:
// Server toolbox: menus, selections, review, live work and actionable results.
// Synthetic data and timings; reports and notifications stay in memory. No remote effects.
using ConsoleMonster.Interactive;
using ConsoleMonster.Glyphs;
using ConsoleMonster.Layout;
using ConsoleMonster.Styling;
using ConsoleMonster.Text;
using ConsoleMonster.Widgets;

// Data: replace these inventories, operations and findings with your own sources.
Node[] inventory = new Node[]
{
    new(Name: "FS01", Domain: "lab.example.test", Site: "Warsaw", Role: "File", Detail: "Windows Server 2022", Offline: ""),
    new(Name: "FS02", Domain: "lab.example.test", Site: "Warsaw", Role: "File", Detail: "Windows Server 2022", Offline: ""),
    new(Name: "WEB01", Domain: "lab.example.test", Site: "Warsaw", Role: "Web", Detail: "Windows Server 2025", Offline: ""),
    new(Name: "SQL01", Domain: "lab.example.test", Site: "Warsaw", Role: "Database", Detail: "Windows Server 2019", Offline: ""),
    new(Name: "FS11", Domain: "lab.example.test", Site: "Berlin", Role: "File", Detail: "Windows Server 2022", Offline: ""),
    new(Name: "WEB11", Domain: "lab.example.test", Site: "Berlin", Role: "Web", Detail: "Windows Server 2025", Offline: ""),
    new(Name: "PRN11", Domain: "lab.example.test", Site: "Berlin", Role: "Print", Detail: "Windows Server 2016", Offline: "offline since 09:12"),
    new(Name: "BKP21", Domain: "lab.example.test", Site: "Dublin", Role: "Backup", Detail: "Windows Server 2022", Offline: ""),
    new(Name: "SQL21", Domain: "lab.example.test", Site: "Dublin", Role: "Database", Detail: "Windows Server 2022", Offline: ""),
    new(Name: "LAB01", Domain: "lab.example.test", Site: "Lab", Role: "Test", Detail: "Windows Server 2025", Offline: ""),
    new(Name: "LAB02", Domain: "lab.example.test", Site: "Lab", Role: "Test", Detail: "Windows Server 2025", Offline: "maintenance until Friday")
};
Check[] catalog = new Check[]
{
    new(Id: "DiskCleanup", Name: "Disk cleanup", Category: "Maintenance", Description: "Removes temporary files and old update caches.", Expected: "cache under 1 GB", Minutes: 3, Changes: true),
    new(Id: "LogRotation", Name: "Log rotation", Category: "Maintenance", Description: "Compresses logs older than 7 days.", Expected: "retention 90 days", Minutes: 2, Changes: true),
    new(Id: "RestartPending", Name: "Pending restart check", Category: "Maintenance", Description: "Reports restarts waiting after updates.", Expected: "no restart pending", Minutes: 1, Changes: false),
    new(Id: "PatchStatus", Name: "Patch status", Category: "Security", Description: "Lists missing security updates.", Expected: "0 missing", Minutes: 2, Changes: false),
    new(Id: "Certificates", Name: "Certificate expiry", Category: "Security", Description: "Finds certificates expiring within 30 days.", Expected: "30+ days", Minutes: 1, Changes: false),
    new(Id: "LocalAdmins", Name: "Local administrators audit", Category: "Security", Description: "Compares local Administrators with the approved list.", Expected: "approved list", Minutes: 1, Changes: false),
    new(Id: "Firewall", Name: "Firewall rules review", Category: "Security", Description: "Flags inbound allow rules open to any address.", Expected: "scoped rules", Minutes: 2, Changes: false),
    new(Id: "EventErrors", Name: "Event log errors", Category: "Health", Description: "Summarizes errors from the last 24 hours.", Expected: "under 20", Minutes: 1, Changes: false),
    new(Id: "Services", Name: "Service health", Category: "Health", Description: "Checks and restarts stopped automatic services.", Expected: "all running", Minutes: 1, Changes: true),
    new(Id: "DiskSpace", Name: "Disk space", Category: "Health", Description: "Warns below 15% and fails below 5% free.", Expected: "15% free", Minutes: 1, Changes: false),
    new(Id: "Uptime", Name: "Uptime and reboots", Category: "Health", Description: "Reports unexpected reboots in the last 30 days.", Expected: "0 unexpected", Minutes: 1, Changes: false)
};
Dictionary<string, (StatusKind Status, string Actual)> findings = new()
{
    ["FS02/PatchStatus"] = (StatusKind.Fail, "3 updates missing for 41 days"),
    ["WEB01/Certificates"] = (StatusKind.Warn, "expires in 24 days"),
    ["SQL01/DiskSpace"] = (StatusKind.Fail, "4% free on data volume"),
    ["FS11/Services"] = (StatusKind.Warn, "1 service restarted"),
    ["FS01/DiskCleanup"] = (StatusKind.Warn, "1.4 GB remains"),
};
List<HistoryRow> history = [new(When: "Mon 19 Oct 21:04", Servers: 3, Tasks: 4, Passed: 10, Warnings: 1, Failed: 1, Elapsed: TimeSpan.FromSeconds(372)), new(When: "Tue 20 Oct 07:30", Servers: 2, Tasks: 3, Passed: 6, Warnings: 0, Failed: 0, Elapsed: TimeSpan.FromSeconds(66)), ];
string reportRoot = "Reports/Toolbox";
Node[] targets = inventory.Where(n => n.Domain == "lab.example.test" && n.Offline == "").Take(4).ToArray();
Check[] checks = catalog.Where(c => new[] { "DiskCleanup", "PatchStatus", "Certificates", "DiskSpace" }.Contains(c.Id)).ToArray();
string domain = "lab.example.test", format = "Html", report = reportRoot, email = "ops@example.test";
int parallel = 3;
bool notify = false, dryRun = false;
List<Work> Plan() => checks.SelectMany(c => targets.Select(n =>
{
    (StatusKind Status, string Actual) outcome = findings.GetValueOrDefault(n.Name + "/" + c.Id, (StatusKind.Pass, c.Expected));
    return new Work(n, c, outcome.Status, outcome.Actual);
})).ToList();
StatusKind Verdict(IEnumerable<Work> work) => work.Any(w => w.Status == StatusKind.Fail) ? StatusKind.Fail : work.Any(w => w.Status == StatusKind.Warn) ? StatusKind.Warn : StatusKind.Pass;
Table TableOf(string[] headers)
{
    Table table = new Table()
    {
        Border = TableBorder.Minimal,
        RecordViewRows = 0
    };
    foreach (string header in headers)
        table.AddColumn(header, HorizontalAlignment.Left);
    return table;
}

IWidget Findings(IEnumerable<Work> work)
{
    Table table = TableOf(new[] { "Server", "Task", "Expected", "Actual" });
    table.Columns[3].Flexible = true;
    foreach (Work w in work.Where(w => w.Status != StatusKind.Pass))
        table.AddRow(w.Node.Name, w.Check.Name, w.Check.Expected, TableCell.FromValue(RichText.Plain(w.Actual, new RichStyle(w.Status == StatusKind.Fail ? ThemeToken.Fail : ThemeToken.Warn))));
    return table;
}

IWidget History()
{
    Table table = TableOf(new[] { "When", "Servers", "Tasks", "Result", "Duration" });
    foreach (HistoryRow h in history.AsEnumerable().Reverse())
        table.AddRow(h.When, h.Servers.ToString(), h.Tasks.ToString(), $"{h.Passed} passed · {h.Warnings} warn · {h.Failed} failed", h.Elapsed.ToString(@"hh\:mm\:ss"));
    return table;
}

IWidget Preview(Check c) => new Rows(new TextBlock(Markup.Escape(c.Description)), new KeyValueList().Add("Group", c.Category).Add("Expected", c.Expected).Add("Duration", "about " + c.Minutes + " min per server").Add("Changes", c.Changes ? "[warn]yes[/]" : "[pass]no[/]").Add("Parameter", c.Id))
{
    Gap = 1
};
// Layout: build the dashboard from the completed and active work.
IWidget Body(List<Work> work, int done, int phase)
{
    Work[] finished = work.Take(done).ToArray();
    Work[] active = phase == 2 ? work.Skip(done).TakeWhile(w => w.Check.Id == work[done].Check.Id).Take(parallel).ToArray() : Array.Empty<Work>();
    SummaryBar summary = new SummaryBar
    {
        Elapsed = TimeSpan.FromSeconds(done * .24 / parallel)
    }.SetProgress(done, work.Count).SetCounter("passed", finished.Count(w => w.Status == StatusKind.Pass), StatusKind.Pass).SetCounter("warnings", finished.Count(w => w.Status == StatusKind.Warn), StatusKind.Warn).SetCounter("failed", finished.Count(w => w.Status == StatusKind.Fail), StatusKind.Fail);
    Phases phases = new Phases();
    string[] names =
    {
        "Discover",
        "Connect",
        "Tasks",
        "Report"
    };
    for (int i = 0; i < names.Length; i++)
        phases.Set(names[i], i < phase ? (i == 2 ? Verdict(finished) : StatusKind.Pass) : i == phase ? StatusKind.Running : StatusKind.Pending);
    Lanes lanes = new Lanes("lanes");
    foreach (Node node in targets)
    {
        Work[] planned = work.Where(w => w.Node == node).ToArray();
        Work[] ready = finished.Where(w => w.Node == node).ToArray();
        Lane lane = lanes.Add(node.Name, RichText.Plain(node.Name + "  " + node.Site), planned.Length);
        lane.Value = ready.Length;
        lane.Passed = ready.Count(w => w.Status == StatusKind.Pass);
        lane.Warned = ready.Count(w => w.Status == StatusKind.Warn);
        lane.Failed = ready.Count(w => w.Status == StatusKind.Fail);
        lane.Status = ready.Length == planned.Length ? Verdict(ready) : active.Any(w => w.Node == node) ? StatusKind.Running : StatusKind.Pending;
        lane.Detail = active.FirstOrDefault(w => w.Node == node)?.Check.Name ?? ready.LastOrDefault()?.Check.Name;
    }

    LogRegion log = new LogRegion()
    {
        ShowElapsed = false,
        PreferredHeight = 7
    };
    log.Write($"Inventory: {domain} · {targets.Length} servers · {work.Count} tasks");
    if (phase >= 1)
        log.Write($"Connecting up to {parallel} servers at a time");
    foreach (Work w in finished.TakeLast(5))
        log.Write($"{w.Node.Name} · {w.Check.Name}: {w.Actual}", w.Status == StatusKind.Fail ? "err" : w.Status == StatusKind.Warn ? "warn" : "info");
    if (phase >= 3)
        log.Write("Preparing " + format.ToUpperInvariant() + " report: " + report);
    if (phase >= 4)
        log.Write(notify ? "Report ready · recipient " + email : "Report ready · " + finished.Count(w => w.Status != StatusKind.Pass) + " findings to review");
    KeyValueList facts = new KeyValueList().Add("Targets", targets.Length + " servers").Add("Tasks", checks.Length + " per server").Add("Parallel", parallel.ToString()).Add("Report", format.ToUpperInvariant()).Add("Dry run", dryRun ? "yes" : "no");
    Columns info = new Columns(new Panel() { Title = "Servers", Content = lanes }, new Panel() { Title = "Run options", Content = facts })
    {
        CollapseBelow = 90
    };
    return new Rows(summary, phases, info, new Panel() { Title = "Findings", Content = Findings(finished) }, new Panel() { Title = "Log", Content = log });
}

// Behaviour: native form/menu navigation, then a bounded run with cancellation and history.
void Execute(MenuContext context, List<Work> work)
{
    RegionWidget body = new RegionWidget(widgetId: "body", content: Body(work, 0, 0));
    Dashboard dashboard = new Dashboard()
    {
        Content = body,
        Title = "[bold]Server toolbox[/]",
        Subtitle = domain,
        Footer = "Ctrl+C cancel · results keep the findings"
    };
    bool completed = false;
    MenuRunResult outcome = context.Run(dashboard, run =>
    {
        void Show(int done, int phase)
        {
            body.Handle(run.Session).Set(Body(work, done, phase));
            run.Session.Delay(TimeSpan.FromMilliseconds(240));
        }

        Show(0, 0);
        Show(0, 1);
        int done = 0;
        foreach (var operation in work.GroupBy(w => w.Check.Id))
        {
            foreach (Work[] batch in operation.Chunk(parallel))
            {
                Show(done, 2);
                done += batch.Length;
            }
        }

        Show(done, 3);
        Show(done, 4);
        MenuRunResult result = Result(work);
        completed = true;
        return result;
    });
    if (!completed)
        return;
    history.Add(new(When: "Tue 20 Oct 09:30", Servers: work.Select(w => w.Node.Name).Distinct().Count(), Tasks: work.Select(w => w.Check.Id).Distinct().Count(), Passed: work.Count(w => w.Status == StatusKind.Pass), Warnings: work.Count(w => w.Status == StatusKind.Warn), Failed: work.Count(w => w.Status == StatusKind.Fail), Elapsed: outcome.Elapsed));
}

MenuRunResult Result(List<Work> work)
{
    MenuRunResult result = new MenuRunResult("Run finished", Verdict(work))
    {
        Summary = $"{work.Count} tasks on {work.Select(w => w.Node.Name).Distinct().Count()} servers. Review the findings and choose the next action.",
        Details = Findings(work)
    };
    result.Figure("passed", work.Count(w => w.Status == StatusKind.Pass).ToString(), StatusKind.Pass);
    result.Figure("warnings", work.Count(w => w.Status == StatusKind.Warn).ToString(), work.Any(w => w.Status == StatusKind.Warn) ? StatusKind.Warn : StatusKind.Pass);
    result.Figure("failed", work.Count(w => w.Status == StatusKind.Fail).ToString(), work.Any(w => w.Status == StatusKind.Fail) ? StatusKind.Fail : StatusKind.Pass);
    result.Next("View report", ctx => ctx.ShowResult(new MenuRunResult("Report · " + format.ToUpperInvariant(), Verdict(work)) { Summary = report, Details = Findings(work) }));
    if (work.Any(w => w.Status == StatusKind.Fail))
        result.Next("Rerun failed tasks", ctx => Execute(ctx, work.Where(w => w.Status == StatusKind.Fail).ToList()));
    result.Next("View history", ctx => ctx.ShowResult(new MenuRunResult("Run history") { Details = History() }));
    return result;
}

Form Options()
{
    Form form = new Form("Options")
    {
